    "summary": "يبدأ الدرس بتعريف الحوض النهري (River Drainage Basin) بأنه المنطقة الأرضية التي تشمل مجرى النهر وشبكة أوديته وروافده ومناطق منبعه ومصبه، وتفصل بين هذه الأحواض حدود تُعرف بخطوط تقسيم المياه. وتتحول الطاقة الكامنة للمياه الجارية إلى طاقة حركية تعتمد على كمية المياه وسرعتها وشكل القناة النهرية، وتتأثر هذه الطاقة بعوامل طبيعية مثل نوع الصخور، ودرجة الانحدار، وكمية التصريف النهري، وعرض القناة، والغطاء النباتي، مما يحدد قدرة النهر على القيام بعمليات الحتّ والنقل.\n\nوفي المراحل المتقدمة من جريان النهر، تتم عمليات الحتّ بأنواعه الثلاثة (الرأسي، والجانبي، والحتّ باتجاه المنابع)، ويقوم النهر بنقل حمولته عبر طرق مختلفة تشمل الجر والقفز لحمولة القاع، والتعليق للحمولة العالقة، والإذابة للمواد الكيميائية. وعندما تقل سرعة النهر في الحوض الأدنى تبدأ عملية الإرساب لتتشكل معالم أرضية مميزة، مثل المراوح الفيضية والدالات المروحية عند مخارج الأودية، والدلتاوات بأشكالها المتنوعة (المثلثي، والقوسي، ورجل الطائر، والمدبب) عند المصبات المائية، بالإضافة إلى الأكواع النهرية والحفر الوعائية في مجرى النهر.",
    "keyPoints": [
      "مفهوم الحوض النهري ومكوناته من مجرى رئيس وروافد ومصب، والحدود الفاصلة بين الأحواض التي تُعرف بخطوط تقسيم المياه.",
      "العوامل المؤثرة في الطاقة النهرية وهي كمية المياه الجارية، وسرعتها، وشكل القناة النهرية نصف الدائري الأقل استهلاكاً للطاقة.",
      "أنواع الحتّ النهري وتشمل الحتّ الرأسي لتعميق المجرى، والحتّ الجانبي لتوسيع القناة، والحتّ باتجاه المنابع الذي يزيد طول المجرى.",
      "طرق نقل الحمولة النهرية وتصنيفها إلى حمولة القاع (بالجر والقفز)، والحمولة العالقة (الطين والطمي)، والحمولة الذائبة كيميائياً.",
      "الأشكال الأرضية الناتجة عن الإرساب النهري مثل المراوح الفيضية، والدلتاوات المتنوعة، والأكواع النهرية، والحفر الوعائية."
    ],
