      "تصنيف الحدود السياسية إلى طبيعية (أنهار، جبال، بحار، غابات) وبشرية (فلكية وهندسية واصطناعية) ومختلطة تجمع بينهما كحدود الأردن وسوريا.",
      "تقسيم المياه البحرية إلى ثلاثة مستويات رئيسة: المياه الإقليمية (سيادة كاملة)، المنطقة الاقتصادية (استغلال الثروات)، والمياه الدولية (أعالي البحار المفتوحة).",
